import{_ as e,o,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Regras de Travessia Planares","description":"","frontmatter":{},"headers":[],"relativePath":"pt/81-位面穿梭规则.md","filePath":"pt/81-位面穿梭规则.md","lastUpdated":null}'),s={name:"pt/81-位面穿梭规则.md"};function t(d,a,n,l,c,p){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="regras-de-travessia-planares" tabindex="-1">Regras de Travessia Planares <a class="header-anchor" href="#regras-de-travessia-planares" aria-label="Permalink to &quot;Regras de Travessia Planares&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>81</td></tr><tr><td>Módulo</td><td>Interação interplanar e regras temporais</td></tr><tr><td>Palavras-chave Principais</td><td>Travessia planar, permissão de travessia, limite de energia, calibração de âncora, prevenção de poluição</td></tr></tbody></table><h2 id="i-posicionamento-juridico-do-ato-de-travessia" tabindex="-1">I. Posicionamento Jurídico do Ato de Travessia <a class="header-anchor" href="#i-posicionamento-juridico-do-ato-de-travessia" aria-label="Permalink to &quot;I. Posicionamento Jurídico do Ato de Travessia&quot;">​</a></h2><p>Travessia planar refere-se ao ato de um indivíduo ou grupo de seres vivos, através de meios tecnológicos ou capacidades de cultivo, atravessar a barreira de leis de um plano para entrar em outro. No quadro jurídico da civilização de simbiose de âncora, a travessia planar é classificada como &quot;ato especial de alto risco&quot; e deve estar sujeita a gestão rigorosa de permissões e supervisão processual. O Artigo 47 da &quot;Constituição de Simbiose&quot; estabelece explicitamente: &quot;Nenhuma organização ou indivíduo pode realizar travessia interplanar sem permissão, nem utilizar a travessia planar para realizar atividades de pilhagem, interferência ou poluição contra civilizações de outros planos.&quot;</p><p>A razão fundamental pela qual a travessia planar requer controle rigoroso é que o próprio ato de travessia pode causar múltiplos impactos no plano-alvo: perturbação de leis, injeção de energia, poluição de consciência, invasão microbiana e interferência cultural, entre outros. Esses impactos, em grau leve, causam anomalias locais no plano-alvo; em grau grave, podem alterar a trajetória evolutiva de sua civilização e até levar ao colapso das leis. Portanto, o objetivo central das regras de travessia é &quot;controlar o impacto externo do ato de travessia dentro de limites aceitáveis&quot;.</p><h2 id="ii-sistema-de-classificacao-de-permissoes-de-travessia" tabindex="-1">II. Sistema de Classificação de Permissões de Travessia <a class="header-anchor" href="#ii-sistema-de-classificacao-de-permissoes-de-travessia" aria-label="Permalink to &quot;II. Sistema de Classificação de Permissões de Travessia&quot;">​</a></h2><p>Hengyuanzhou implementa um sistema de classificação de permissões de travessia planar, dividindo as permissões em quatro níveis de acordo com o propósito da travessia, o tipo de plano-alvo e a qualificação do viajante:</p><table tabindex="0"><thead><tr><th>Nível de Permissão</th><th>Cenário Aplicável</th><th>Agência Aprovadora</th><th>Validade</th><th>Condições Adicionais</th></tr></thead><tbody><tr><td>Nível A (Observação Arqueológica)</td><td>Arqueologia puramente observacional, sem qualquer contato físico</td><td>Agência de Administração Planares</td><td>Missão única</td><td>Deve utilizar o esquema de espelho de cópia + espaço isolado</td></tr><tr><td>Nível B (Intercâmbio Acadêmico)</td><td>Intercâmbio limitado de conhecimento com a civilização do plano-alvo</td><td>Agência de Administração Planares + Ministério da Cultura</td><td>Máximo de um ano</td><td>Deve assinar acordo de não interferência mútua</td></tr><tr><td>Nível C (Cooperação de Recursos)</td><td>Cooperação de recursos e tecnologia sob premissa de igualdade e benefício mútuo</td><td>Aprovação especial do Conselho de Âncoras</td><td>Máximo de três anos</td><td>Deve obter consentimento da civilização do plano-alvo</td></tr><tr><td>Nível D (Intervenção de Emergência)</td><td>Intervenção humanitária quando o plano-alvo enfrenta crise de nível de extinção</td><td>Resolução de emergência do Conselho de Âncoras</td><td>Durante a crise</td><td>Deve apresentar relatório completo de intervenção posteriormente</td></tr></tbody></table><p>Qualquer nível de permissão de travessia proíbe os seguintes atos: pilhar a energia de origem do plano-alvo, disseminar forçosamente a ideologia do próprio plano, realizar modificações genéticas ou de consciência sem consentimento, estabelecer bases militares permanentes no plano-alvo, e qualquer forma de domínio colonial.</p><h2 id="iii-requisitos-tecnologicos-e-limite-de-energia-para-travessia" tabindex="-1">III. Requisitos Tecnológicos e Limite de Energia para Travessia <a class="header-anchor" href="#iii-requisitos-tecnologicos-e-limite-de-energia-para-travessia" aria-label="Permalink to &quot;III. Requisitos Tecnológicos e Limite de Energia para Travessia&quot;">​</a></h2><p>A travessia planar requer o cumprimento de condições tecnológicas rigorosas. Primeiramente, o viajante deve possuir cultivo de terceiro estágio (Estado de Transformação do Vazio) ou superior do &quot;sistema de regulação jurídica espacial&quot;, ou transportar uma aeronave de travessia planar que atenda aos padrões. Em segundo lugar, tanto o ponto de partida quanto o ponto de chegada da travessia devem ter âncoras para calibração de coordenadas; a travessia cega sem posicionamento de âncora é estritamente proibida.</p><p>O consumo de energia durante o processo de travessia é diretamente proporcional à intensidade da barreira de leis do plano-alvo. Hengyuanzhou estabeleceu uma &quot;tabela de limite de energia de travessia&quot; padronizada, e a energia mínima necessária para a travessia de diferentes tipos de planos é a seguinte:</p><ul><li>Plano de base material: 1000 unidades de energia padrão</li><li>Plano de manifestação de energia: 5000 unidades de energia padrão</li><li>Plano dominado por consciência: 20000 unidades de energia padrão</li><li>Plano de leis quebradas: 50000 unidades de energia padrão (e taxa de sucesso inferior a 30%)</li><li>Plano próximo à origem: valor teórico acima de 100000, atualmente sem registros de sucesso</li></ul><p>A energia de travessia deve ser transportada pelo próprio viajante ou aeronave, sendo proibido extrair energia do plano-alvo para o processo de travessia. Esta disposição visa evitar que o ato de travessia cause pilhagem de energia no plano-alvo.</p><h2 id="iv-prevencao-e-controle-de-poluicao-no-processo-de-travessia" tabindex="-1">IV. Prevenção e Controle de Poluição no Processo de Travessia <a class="header-anchor" href="#iv-prevencao-e-controle-de-poluicao-no-processo-de-travessia" aria-label="Permalink to &quot;IV. Prevenção e Controle de Poluição no Processo de Travessia&quot;">​</a></h2><p>Um dos maiores riscos da travessia planar é a &quot;poluição interplanar&quot;, que inclui poluição biológica (transportar microrganismos do próprio plano para o plano-alvo), poluição de energia (interferência de resíduos de energia do próprio plano nas leis do plano-alvo) e poluição de consciência (flutuações de consciência do viajante afetando o domínio de consciência do plano-alvo).</p><p>Para prevenir e controlar a poluição, todos os viajantes devem concluir o &quot;programa de purificação de três níveis&quot; antes da partida:</p><ol><li><strong>Purificação biológica</strong>: Realizar triagem e eliminação microbiana por 72 horas em espaço isolado, garantindo que não transportem nenhum patógeno do próprio plano</li><li><strong>Purificação de energia</strong>: Ajustar a frequência de energia do viajante para uma faixa compatível com o plano-alvo através do dispositivo de calibração de âncora, reduzindo reações de rejeição de energia</li><li><strong>Purificação de consciência</strong>: Realizar treinamento de bloqueio de consciência, garantindo que durante o processo de travessia não liberem ativamente flutuações de vontade que possam interferir no domínio de consciência do plano-alvo</li></ol><p>Além disso, o escopo de atividades do viajante no plano-alvo é estritamente limitado à &quot;área delimitada pela permissão de travessia&quot;, sendo proibida a disseminação não autorizada. Após retornar ao próprio plano, o viajante deve novamente passar por observação isolada por um período não inferior a 30 dias convertidos pela velocidade de fluxo temporal do plano-alvo.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>As regras de travessia planar são a primeira linha de defesa de segurança da interação interplanar. Através de três mecanismos — classificação de permissões, barreiras tecnológicas e prevenção de poluição — garantem que o ato de travessia opere sempre na trilha de &quot;baixo impacto, rastreabilidade e responsabilização&quot;. O objetivo final das regras não é limitar o intercâmbio entre civilizações, mas fazer com que o intercâmbio ocorra de forma simbiótica, em vez de predatória.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>80-Teoria e Classificação dos Planos</li><li>88-Diretrizes Éticas Interplanares</li><li>62-Implementação Tecnológica Jurídica Espacial</li></ul>',23)])])}const v=e(s,[["render",t]]);export{m as __pageData,v as default};
